import React, { useState, useEffect } from 'react';
import GlobalStyle from './styles/GlobalStyle';
import styled from 'styled-components';
import axios from 'axios';

import Header from './components/Header';
import Equipment from './components/Equipment';
import EquipmentSearch from './components/EquipmentSearch';
import SelectedSidebar from './components/SelectedSidebar';
import TrainingTips from './components/TrainingTips';
import { trainingTipsData } from './data/trainingTipsData';

const MainContainer = styled.div`
  display: flex;
  justify-content: space-between;
  margin: 20px auto;
  max-width: 1200px;
`;

const ContentArea = styled.div`
  flex: 2;
  padding-right: 20px;
`;

const SidebarArea = styled.div`
  flex: 1;
  padding-left: 20px;
`;

function App() {
  const [equipmentData, setEquipmentData] = useState([]);
  const [filteredEquipment, setFilteredEquipment] = useState([]);
  const [selectedEquipment, setSelectedEquipment] = useState([]);
  const [currentPage, setCurrentPage] = useState(1); // Pagination state
  const [itemsPerPage] = useState(20); // 5 rows × 4 columns = 20 items per page
  const [priceRange, setPriceRange] = useState({ min: '', max: '' }); // Price filter

  // Fetch data from Flask backend
  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await axios.get('http://localhost:5000/api/competitivecyclist');
        const rawData = response.data;

        const flattenedData = Object.values(rawData).flatMap(category =>
          Object.values(category).flat()
        );

        setEquipmentData(flattenedData);
        setFilteredEquipment(flattenedData);
      } catch (error) {
        console.error('Error fetching data:', error.message);
      }
    };

    fetchData();
  }, []);

  // Handle search input to filter the equipment list
  const handleSearch = (searchTerm) => {
    const filtered = equipmentData.filter(item =>
      item.Name.toLowerCase().includes(searchTerm.toLowerCase())
    );
    setFilteredEquipment(filtered);
    setCurrentPage(1); // Reset to page 1 when filtering
  };

  // Handle price filtering
  const handlePriceFilter = () => {
    const min = parseFloat(priceRange.min) || 0;
    const max = parseFloat(priceRange.max) || Infinity;

    const filtered = equipmentData.filter(item => item.Price >= min && item.Price <= max);
    setFilteredEquipment(filtered);
    setCurrentPage(1); // Reset to page 1 when filtering
  };

  // Handle selecting an equipment item
  const handleSelect = (item) => {
    const itemWithPrice = { ...item, price: item.Price || '$100' };
    setSelectedEquipment((prev) =>
      prev.find((i) => i.id === itemWithPrice.id)
        ? prev.filter((i) => i.id !== itemWithPrice.id)
        : [...prev, itemWithPrice]
    );
  };

  const handleRemoveItem = (id) => {
    setSelectedEquipment(selectedEquipment.filter((item) => item.id !== id));
  };

  // Pagination logic
  const indexOfLastItem = currentPage * itemsPerPage;
  const indexOfFirstItem = indexOfLastItem - itemsPerPage;
  const currentItems = filteredEquipment.slice(indexOfFirstItem, indexOfLastItem);

  const totalPages = Math.ceil(filteredEquipment.length / itemsPerPage);

  const nextPage = () => setCurrentPage((prev) => Math.min(prev + 1, totalPages));
  const prevPage = () => setCurrentPage((prev) => Math.max(prev - 1, 1));

  return (
    <>
      <GlobalStyle />
      <Header />

      <MainContainer>
        <ContentArea>
          <EquipmentSearch onSearch={handleSearch} />
          <div style={{ display: 'flex', gap: '10px', marginBottom: '10px' }}>
            <input
              type="number"
              placeholder="Min Price"
              value={priceRange.min}
              onChange={(e) => setPriceRange({ ...priceRange, min: e.target.value })}
            />
            <input
              type="number"
              placeholder="Max Price"
              value={priceRange.max}
              onChange={(e) => setPriceRange({ ...priceRange, max: e.target.value })}
            />
            <button onClick={handlePriceFilter}>Filter</button>
          </div>

          <Equipment equipment={currentItems} handleSelect={handleSelect} />

          <div style={{ display: 'flex', justifyContent: 'center', marginTop: '10px' }}>
            <button onClick={prevPage} disabled={currentPage === 1}>
              Previous
            </button>
            <span style={{ margin: '0 10px' }}>
              Page {currentPage} of {totalPages}
            </span>
            <button onClick={nextPage} disabled={currentPage === totalPages}>
              Next
            </button>
          </div>
        </ContentArea>

        <SidebarArea>
          <SelectedSidebar selectedItems={selectedEquipment} removeItem={handleRemoveItem} />
        </SidebarArea>
      </MainContainer>
    </>
  );
}

export default App;
